<?php
declare(strict_types=1);
namespace App\Command;
use App\Imperium\Runtime\Conscription\AuthorshipResidentConscriptionService; use Symfony\Component\Console\Attribute\AsCommand; use Symfony\Component\Console\Command\Command; use Symfony\Component\Console\Input\InputArgument; use Symfony\Component\Console\Input\InputInterface; use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name: 'imperium:conscription:fulfill-sanctographer', description: 'Instantiate and qualify the exact canonical Sanctographer')]
final class ConscriptionFulfillSanctographerCommand extends Command { public function __construct(private readonly AuthorshipResidentConscriptionService $service) { parent::__construct(); } protected function configure(): void { $this->addArgument('commission-id', InputArgument::REQUIRED); } protected function execute(InputInterface $input, OutputInterface $output): int { try { $r = $this->service->fulfill('hagiography', (string) $input->getArgument('commission-id')); } catch (\Throwable $e) { $output->writeln('<error>REFUSED</error> '.$e->getMessage()); return self::FAILURE; } $d=$r['delivery']; $output->writeln('<info>SANCTOGRAPHER_MANIFESTATION_QUALIFIED</info> '.$d['delivery_id']); $output->writeln('Recruiter: '.$r['recruiter']['manifestation_id']); $output->writeln('Candidate: '.$d['candidate']['manifestation_id']); $output->writeln('Status: '.$d['candidate']['status']); $output->writeln('Authorship authority: NOT GRANTED'); $output->writeln('Subordinate Chronicler resolution: NOT GRANTED'); $output->writeln('Seat binding authority: NOT GRANTED'); $output->writeln('Recipient acceptance: NOT RECORDED'); $output->writeln('Execution authority: NOT GRANTED'); return self::SUCCESS; } }
